<?php require_once __DIR__.'/auth.php';api_auth();header('Content-Type: application/json');$f=__DIR__.'/media_map.json';$map=file_exists($f)?json_decode(file_get_contents($f),true):[];if(!is_array($map))$map=[];$a=$_GET['action']??$_POST['action']??'list';$path=trim($_POST['path']??'');$protected=(bool)preg_match('/logo|favicon|instagram|facebook|youtube/i',$path);if($a==='list'){require __DIR__.'/media_catalog.php';exit;}if(!$path||strpos($path,'..')!==false){http_response_code(422);echo json_encode(['error'=>'Invalid path']);exit;}if($a==='hide'&&$protected){http_response_code(422);echo json_encode(['error'=>'This asset cannot be hidden']);exit;}if(in_array($a,['hide','show','reset'],true)){if(!isset($map[$path]))$map[$path]=['hidden'=>false];if($a==='hide')$map[$path]['hidden']=true;if($a==='show')$map[$path]['hidden']=false;if($a==='reset')unset($map[$path]['url']);file_put_contents($f,json_encode($map,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);echo json_encode(['ok'=>true]);exit;}http_response_code(400);echo json_encode(['error'=>'Unsupported action']);
